@PostMapping
public ResponseEntity<String> chat(@RequestBody ChatRequest request) {
  String response = chatClient.prompt(request.getMessage())
    .system("당신은 친절한 AI 비서입니다. 한국어로 응답해주세요.")
    .call()
    .content();
  return ResponseEntity.ok(response);
}

public String askDocument(String question) {
  List<Document> relevantDocs = vectorStore.similaritySearch(question, 3);
  StringBuilder contextBuilder = new StringBuilder();
  for (Document doc : relevantDocs) {
    contextBuilder.append(doc.getContent()).append("\n\n");
  }
  String prompt = String.format(
    """
     다음 정보를 바탕으로 질문에 답변해주세요:
    %s
     질문:
    %s
    """,
    contextBuilder.toString(),
    question
  );
  return chatClient.prompt(prompt).call().content();
}

public List<Product> recommendProducts(String userPreferences) {
  PromptTemplate template = new PromptTemplate(
    """
     사용자 선호도: {preferences}
    위 정보를 바탕으로 5개의 제품을 추천해주세요.
    각 제품은 이름(name), 가격(price), 설명(description)을 포함해야 합니다.
    JSON 배열 형식으로 응답해주세요.
    """
  );
  Prompt prompt = template.create(Map.of("preferences", userPreferences));
  return chatClient.prompt(prompt).call().entity(new ParameterizedTypeReference<List<Product>>() {});
}

public String getResponse(String question) {
  return responseCache.get(question, q -> chatClient.prompt(q).call().content());
}

